// SmartHelmet/Software/src/App.jsx

import { useState } from 'react';
import SplashScreen from './components/SplashScreen';
import Dashboard from './pages/Dashboard';
import './styles/global.css';

const TRANSITION_MS = 900; // must match CSS exit animation duration

function App() {
  const [phase, setPhase] = useState('splash'); // splash | exiting | dashboard

  const handleLaunch = () => {
    setPhase('exiting');
    setTimeout(() => setPhase('dashboard'), TRANSITION_MS);
  };

  return (
    <>
      {/* Pre-mount dashboard underneath during the exit phase for a smooth crossfade and asset loading */}
      {phase !== 'splash' && (
        <div className="dashboard-enter">
          <Dashboard />
        </div>
      )}

      {/* Splash screen overlay (z-index ensures it sits on top) */}
      {(phase === 'splash' || phase === 'exiting') && (
        <SplashScreen
          onLaunch={handleLaunch}
          exiting={phase === 'exiting'}
        />
      )}
    </>
  );
}

export default App;
